package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestCmsRelocationRewritesOnlyDocrootTokens(t *testing.T) {
	stage := t.TempDir()
	files := []struct{ name, input, expected string }{
		{".gitignore", `# Dependencies managed by Composer.
/recipes
/vendor
/web/core
/web/libraries
/web/modules/contrib
/web/profiles/contrib
/web/themes/contrib
# Site-specific settings and files.
/web/sites/*/settings*.php
/web/sites/*/services*.yml
/web/sites/*/files
/web/sites/*/private
# Test site directories generated by automated testing.
/web/sites/simpletest
# PHP scripts scaffolded into the web root by Drupal core.
/web/*.php
# Leave web/example alone in comments.
/someweb/core
/build/web/core
`, `# Dependencies managed by Composer.
/recipes
/vendor
/docroot/core
/docroot/libraries
/docroot/modules/contrib
/docroot/profiles/contrib
/docroot/themes/contrib
# Site-specific settings and files.
/docroot/sites/*/settings*.php
/docroot/sites/*/services*.yml
/docroot/sites/*/files
/docroot/sites/*/private
# Test site directories generated by automated testing.
/docroot/sites/simpletest
# PHP scripts scaffolded into the web root by Drupal core.
/docroot/*.php
# Leave web/example alone in comments.
/someweb/core
/build/web/core
`},
		{"AGENTS.md", "- Do not commit `vendor/` or uploaded files under `web/sites/*/files`.\n" +
			"- Put custom code in `web/modules/custom` and `web/themes/custom`.\n" +
			"- See `someweb/core`, `build/web/core`, and `https://example.test/web/core`.\n",
			"- Do not commit `vendor/` or uploaded files under `docroot/sites/*/files`.\n" +
				"- Put custom code in `docroot/modules/custom` and `docroot/themes/custom`.\n" +
				"- See `someweb/core`, `build/web/core`, and `https://example.test/web/core`.\n"},
	}
	for _, file := range files {
		if err := os.WriteFile(filepath.Join(stage, file.name), []byte(file.input), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	if err := (drupalSiteIntent{Webroot: "docroot"}).relocateCmsProjectFiles(stage); err != nil {
		t.Fatal(err)
	}
	for _, file := range files {
		assertFileText(t, filepath.Join(stage, file.name), file.expected)
	}
}

func TestLegacyDrupalScaffoldArgumentsReportTaskUsage(t *testing.T) {
	for _, legacy := range []struct {
		task string
		args []string
		form string
	}{
		{"drupal-scaffold", []string{"11"}, "lando-drupal-scaffold <major> <webroot> --testing=<bool>"},
		{"drupal-cms-scaffold", nil, "lando-drupal-cms-scaffold <webroot> --testing=<bool>"},
	} {
		t.Run(legacy.task, func(t *testing.T) {
			fixture := newScaffoldFixture(t, nil)
			if code := fixture.run(t, legacy.task, legacy.args...); code != 64 {
				t.Fatalf("expected usage exit 64, got %d: %s", code, fixture.stderr.String())
			}
			for _, token := range []string{legacy.form, legacy.task + " task cmd", ".lando.yml"} {
				if !strings.Contains(fixture.stderr.String(), token) {
					t.Fatalf("missing %q in %s", token, fixture.stderr.String())
				}
			}
			assertDirectoryNames(t, fixture.appRoot, nil)
		})
	}
}
